using System; using System.Text.Json; using System.Threading; using System.Threading.Tasks; using Parcs.Agent.Runtime;
public class Part { public double Value { get; set; } }
public class Integrate : IAgentComputation { public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct) { int k = int.Parse(input.Parameters["k"]); double a = 8.0*k/32, b = 8.0*(k+1)/32, h=(b-a)/10000.0, sum=Math.Exp(-a/4)*Math.Cos(a+0.5*Math.Sin(2*a))+Math.Exp(-b/4)*Math.Cos(b+0.5*Math.Sin(2*b)); for(int i=1;i<10000;i++){ double x=a+i*h; double f=Math.Exp(-x/4)*Math.Cos(x+0.5*Math.Sin(2*x)); sum+=(i%2==0?2.0:4.0)*f; } return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new Part { Value=sum*h/3.0 }))); } }
public class Reduce : IAgentComputation { public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct) { double total=0; for(int j=0;j<32;j++){ var xs=input.GetPreviousOutputs(j); foreach(var s in xs) if(s!=null) total+=JsonSerializer.Deserialize<Part>(s).Value; } return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new Part { Value=total }))); } }
